def find_max(numbers):
    m = numbers[0]
    for i in numbers:
        if i > m:
            m = i
    return m

def process_multiple_lists(list_of_lists):
    results = []
    for n in list_of_lists:
        m = n[0]
        for k in n:
            if k > m:
                m = k
        results.append(m)
    return results

def find_max_with_index(numbers):
    max_val = numbers[0]
    max_idx = 0
    for j, val in enumerate(numbers):
        if val > max_val:
            max_val = val
            max_idx = j
    return max_val, max_idx

def double_and_find_max(numbers):
    doubled_numbers = []
    for i in numbers:
        doubled_numbers.append(i * 2)
    max_d = doubled_numbers[0]
    for j in doubled_numbers:
        if j > max_d:
            max_d = j
    return max_d

def filter_and_find_max(numbers, threshold):
    filtered_numbers = []
    for k in numbers:
        if k > threshold:
            filtered_numbers.append(k)
    if not filtered_numbers:
        return None
    m = filtered_numbers[0]
    for n in filtered_numbers:
        if n > m:
            m = n
    return m

