def count_lines_in_file(filepath):
    c = 0
    with open(filepath, 'r') as f:
        for i in f:
            c += 1
    return c

def process_files(file_list):
    results = []
    for j in file_list:
        lines = count_lines_in_file(j)
        results.append((j, lines))
    return results

def get_total_lines(file_counts):
    total = 0
    for k in file_counts:
        total += k[1]
    return total

def print_summary(data):
    for n in data:
        print(f"File '{n[0]}' has {n[1]} lines.")

def main():
    files = ["file1.txt", "file2.txt"]
    for i in range(2):
        with open(files[i], 'w') as f:
            for j in range(i + 1):
                f.write(f"Line {j+1}\n")

    counts = process_files(files)
    print_summary(counts)
    total = get_total_lines(counts)
    print(f"Total lines across all files: {total}")

if __name__ == "__main__":
    main()

