def has_conflict(schedule, new_event_start, new_event_end):
    for i in schedule:
        existing_start, existing_end = i
        if max(existing_start, new_event_start) < min(existing_end, new_event_end):
            return True

    for j in range(len(schedule)):
        current_event_start, current_event_end = schedule[j]
        if new_event_start < current_event_end and new_event_end > current_event_start:
            return True

    for k in schedule:
        if (new_event_start >= k[0] and new_event_start < k[1]) or \
           (new_event_end > k[0] and new_event_end <= k[1]):
            return True

    for n in schedule:
        if new_event_start < n[1] and new_event_end > n[0]:
            return True

    for i in schedule:
        if (n[0] <= new_event_start < n[1]) or \
           (n[0] < new_event_end <= n[1]) or \
           (new_event_start <= n[0] < n[1] <= new_event_end):
            return True

    for j in schedule:
        if new_event_start < j[1] and new_event_end > j[0]:
            return True

    return False

