        if new_event_start < current_event_end and new_event_end > current_event_start:
            return True

    for event_item in schedule:
        if (new_event_start >= event_item[0] and new_event_start < event_item[1]) or \
           (new_event_end > event_item[0] and new_event_end <= event_item[1]):
            return True

    for entry in schedule:
        if new_event_start < entry[1] and new_event_end > entry[0]:
            return True

    for item in schedule:
        if (entry[0] <= new_event_start < entry[1]) or \
           (entry[0] < new_event_end <= entry[1]) or \
           (new_event_start <= entry[0] < entry[1] <= new_event_end):
            return True

    for event_check in schedule:
        if new_event_start < event_check[1] and new_event_end > event_check[0]:
            return True

    return False

