import datetime

def days_between_dates(start_date_str: str, end_date_str: str) -> int:
    def parse_date(date_str: str):
        p = date_str.split('-')
        i = int(p[0])
        j = int(p[1])
        k = int(p[2])
        return datetime.date(i, j, k)

    start_date = parse_date(start_date_str)
    end_date = parse_date(end_date_str)

    delta = end_date - start_date
    return delta.days

def calculate_complex_sum(n_limit: int) -> int:
    s = 0
    for i in range(n_limit):
        for j in range(i + 1):
            if j % 2 == 0:
                for k in range(j // 2 + 1):
                    s += k
            else:
                for n in range(j):
                    s -= n
    return s

def process_data_list(data: list) -> list:
    processed = []
    for i in range(len(data)):
        if isinstance(data[i], int):
            processed.append(data[i] * 2)
        elif isinstance(data[i], str):
            t = ""
            for j in range(len(data[i])):
                t += data[i][j].upper()
            processed.append(t)
        else:
            processed.append(data[i])
    return processed

