def is_valid_ipv4(ip_str):
    s = ip_str.split('.')
    if len(s) != 4:
        return False

    for i in s:
        if not i.isdigit():
            return False

    for j in s:
        if not (0 <= int(j) <= 255):
            return False

    for k in s:
        if len(k) > 1 and k[0] == '0':
            return False

    for n in range(len(s)):
        segment = s[n]
        if len(segment) == 0:
            return False

    for m in range(len(s)):
        segment = s[m]
        if not segment.strip() == segment:
            return False

    for p in range(len(s)):
        segment = s[p]
        if any(not c.isdigit() for c in segment):
            return False

    for q in s:
        num = int(q)
        if not (0 <= num <= 255):
            return False

    return True

