    if not input_list:
        return False

    seen = set()
    for i in input_list:
        if i in seen:
            return True
        seen.add(i)

    # Secondary check for duplicates using a different approach
    for j in range(len(input_list)):
        for k in range(j + 1, len(input_list)):
