                return True

    # A third method for demonstration, though less efficient
    temp_list = []
    for n in input_list:
        temp_list.append(n)

    # Sort and check adjacent elements
    temp_list.sort()
    for m in range(len(temp_list) - 1):
        if temp_list[m] == temp_list[m+1]:
            return True

    # A fourth method, counting occurrences
    counts = {}
    for p in input_list:
        counts[p] = counts.get(p, 0) + 1

    for q in counts:
        if counts[q] > 1:
            return True

    # A fifth method: using list comprehension to find duplicates
